<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use App\Models\Subscription;
class Commerce {
 public static function price(array $v,int $user):array {
  $kind=$v['kind'];$id=$v['item_id']??null;$currency=$v['currency_code'];$period=(int)($v['period_days']??30);$data=[];
  if(!DB::table('currencies')->where('code',$currency)->where('enabled',true)->exists())throw new \DomainException('Currency unavailable');
  if($kind==='topup'){$amount=(int)($v['amount_minor']??0);if($currency!=='UGX'||$amount<1000||$amount>1000000)throw new \DomainException('Top up UGX 1,000 to 1,000,000');}
  elseif($kind==='plan'){$p=DB::table('membership_plans')->where('code',$id)->whereIn('code',['gold','pro'])->where('enabled',true)->first();$amount=$p?DB::table('membership_prices')->where('plan_code',$id)->where('currency_code',$currency)->where('period_days',$period)->value('amount_minor'):null;$data=['plan'=>$id,'period_days'=>$period];}
  elseif($kind==='pack'){$p=DB::table('super_like_packs')->where('id',$id)->where('enabled',true)->where('currency_code',$currency)->first();$amount=$p?->amount_minor;$data=['quantity'=>$p?->quantity,'reward_type'=>$p?->reward_type];}
  elseif($kind==='ticket'){$p=DB::table('experiences')->where('id',$id)->lockForUpdate()->first();if(!$p||!$p->published||$p->is_demo||$p->ends_at<=now()||$p->currency_code!==$currency)throw new \DomainException('Event unavailable');if(DB::table('experience_tickets')->where('experience_id',$id)->where('user_id',$user)->where('status','confirmed')->exists())throw new \DomainException('You already have a ticket');if(DB::table('experience_tickets')->where('experience_id',$id)->where('status','confirmed')->count()>=$p->capacity)throw new \DomainException('Sold out');$amount=$p->amount_minor;}
  elseif($kind==='content'){$p=DB::table('premium_content')->where('id',$id)->where('published',true)->where('currency_code',$currency)->first();if(!$p)throw new \DomainException('Content unavailable');$creator=DB::table('users')->where('id',$p->creator_id)->first();$viewer=DB::table('users')->where('id',$user)->first();if(!$creator||$creator->is_block||in_array((string)$user,explode(',',(string)$creator->blocked_users),true)||in_array((string)$creator->id,explode(',',(string)$viewer->blocked_users),true))throw new \DomainException('Content unavailable');if($p->creator_id===$user||DB::table('content_unlocks')->where('content_id',$id)->where('user_id',$user)->exists())throw new \DomainException('Already unlocked');$amount=$p->amount_minor;$data=['creator_id'=>$p->creator_id];}
  else throw new \DomainException('Invalid purchase');
  if(!isset($amount) || $amount<=0)throw new \DomainException('Price not configured');return ['amount_minor'=>(int)$amount,'snapshot'=>json_encode($data)];
 }
 public static function apply($order):void{
  $snapshot=json_decode($order->snapshot,true);
  if($order->kind==='topup'){DB::table('cash_wallets')->insertOrIgnore(['user_id'=>$order->user_id,'currency_code'=>$order->currency_code,'balance_minor'=>0,'created_at'=>now(),'updated_at'=>now()]);DB::table('cash_wallets')->where('user_id',$order->user_id)->where('currency_code',$order->currency_code)->increment('balance_minor',$order->amount_minor);DB::table('cash_wallets')->where('user_id',$order->user_id)->where('currency_code',$order->currency_code)->where('balance_minor','>=',0)->update(['frozen'=>false]);}
  elseif($order->kind==='pack'){if(($snapshot['reward_type']??'star')==='coins'){DB::table('users')->where('id',$order->user_id)->increment('wallet',$snapshot['quantity']);FundedCoins::issue($order,(int)$snapshot['quantity']);}else {PremiumAccess::usage($order->user_id);DB::table('premium_usage')->where('user_id',$order->user_id)->increment('purchased_stars',$snapshot['quantity']);}}
  elseif($order->kind==='plan'){$existing=Subscription::where('user_id',$order->user_id)->where('provider','wallet')->where('plan',$order->item_id)->active()->max('expires_at');$from=$existing?\Carbon\Carbon::parse($existing)->max(now()):now();Subscription::create(['user_id'=>$order->user_id,'plan'=>$order->item_id,'provider'=>'wallet','product_id'=>$order->item_id,'provider_txn_id'=>$order->id,'status'=>'active','started_at'=>now(),'expires_at'=>$from->addDays($snapshot['period_days'])]);}
  elseif($order->kind==='ticket')DB::table('experience_tickets')->insert(['user_id'=>$order->user_id,'experience_id'=>$order->item_id,'ticket_code'=>(string)Str::uuid(),'status'=>'confirmed','created_at'=>now(),'updated_at'=>now()]);
  elseif($order->kind==='content'){DB::table('content_unlocks')->insert(['user_id'=>$order->user_id,'content_id'=>$order->item_id,'order_id'=>$order->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('creator_sales')->insert(['order_id'=>$order->id,'creator_id'=>$snapshot['creator_id'],'currency_code'=>$order->currency_code,'gross_minor'=>$order->amount_minor,'created_at'=>now(),'updated_at'=>now()]);}
 }
 // Provider response is fetched server-to-server; callback query/body is never evidence of payment.
 public static function reconcile(string $id,array $provider):bool{return DB::transaction(function()use($id,$provider){$o=DB::table('commerce_orders')->where('id',$id)->first();if(!$o||$o->kind!=='topup')throw new \DomainException('Unknown payment');if(!DB::table('users')->where('id',$o->user_id)->exists())throw new \DomainException('Deleted account payment requires reconciliation');DB::table('users')->where('id',$o->user_id)->lockForUpdate()->first();$o=DB::table('commerce_orders')->where('id',$id)->lockForUpdate()->first();$decimals=(int)DB::table('currencies')->where('code',$o->currency_code)->value('decimals');
  if(($provider['merchant_reference']??'')!==$o->id || ($provider['currency']??'')!==$o->currency_code || !is_numeric($provider['amount']??null) || (int)round($provider['amount']*(10**$decimals))!==$o->amount_minor)throw new \DomainException('Payment details do not match');
  $status=(int)($provider['status_code']??-1);
  if($status===3 && $o->status==='settled'){DB::table('cash_wallets')->where('user_id',$o->user_id)->where('currency_code',$o->currency_code)->decrement('balance_minor',$o->amount_minor);DB::table('cash_wallets')->where('user_id',$o->user_id)->where('currency_code',$o->currency_code)->where('balance_minor','<',0)->update(['frozen'=>true]);DB::table('cash_ledger')->insert(['order_id'=>$o->id.':reversed','user_id'=>$o->user_id,'currency_code'=>$o->currency_code,'amount_minor'=>-$o->amount_minor,'kind'=>'reversal','created_at'=>now(),'updated_at'=>now()]);DB::table('commerce_orders')->where('id',$id)->update(['status'=>'reversed','updated_at'=>now()]);return false;}
  if(in_array($o->status,['settled','reversed'],true))return $o->status==='settled';
  if($status!==1){DB::table('commerce_orders')->where('id',$id)->update(['status'=>$status===2?'failed':'pending','updated_at'=>now()]);return false;}
  self::apply($o);DB::table('cash_ledger')->insert(['order_id'=>$id,'user_id'=>$o->user_id,'currency_code'=>$o->currency_code,'amount_minor'=>$o->amount_minor,'kind'=>'topup','created_at'=>now(),'updated_at'=>now()]);DB::table('commerce_orders')->where('id',$id)->update(['status'=>'settled','updated_at'=>now()]);return true;
 });}
}
